#include <bits/stdc++.h>

#define rep(i, n) for (int i = 0; i < (n); i++)
#define repr(i, n) for (int i = (n) - 1; i >= 0; i--)

using namespace std;
using ll = long long;

struct mincostflow {
  struct edge {
    int v;
    long long c;
    long long w;
    int r;
  };

  vector<vector<edge>> G;

  mincostflow(int n) : G(n) {}

  void add(int u, int v, long long c, long long w) {
    int i = G[u].size();
    int j = G[v].size();
    G[u].push_back({v, c, w, j});
    G[v].push_back({u, 0, -w, i});
  }

  long long run(int s, int t, long long f) {
    const int N = G.size();
    long long res = 0;
    vector<long long> H(N);
    vector<long long> D(N);
    const long long INF = 1e18;
    vector<int> PE(N), PV(N);
    while (f > 0) {
      priority_queue<pair<long long, int>> q;
      fill(D.begin(), D.end(), INF);
      D[s] = 0;
      q.emplace(0, s);
      while (!q.empty()) {
        long long d = -q.top().first;
        int u = q.top().second;
        q.pop();
        if (D[u] < d) continue;
        for (int i = 0; i < G[u].size(); i++) {
          edge e = G[u][i];
          if (e.c > 0 && D[e.v] > D[u] + e.w + H[u] - H[e.v]) {
            D[e.v] = D[u] + e.w + H[u] - H[e.v];
            q.emplace(-D[e.v], e.v);
            PV[e.v] = u;
            PE[e.v] = i;
          }
        }
      }
      if (D[t] == INF) return -1;
      for (int i = 0; i < N; i++) H[i] += D[i];
      long long d = f;
      for (int i = t; i != s; i = PV[i]) {
        d = min(d, G[PV[i]][PE[i]].c);
      }
      f -= d;
      res += d * H[t];
      for (int i = t; i != s; i = PV[i]) {
        edge &e = G[PV[i]][PE[i]];
        e.c -= d;
        G[i][e.r].c += d;
      }
    }
    return res;
  }
};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  ll N, M, K, C, D;
  cin >> N >> M >> K >> C >> D;
  vector<int> A(K);
  rep(i, K) cin >> A[i], A[i]--;
  vector<int> us(M), vs(M);
  rep(i, M) {
    cin >> us[i] >> vs[i];
    us[i]--;
    vs[i]--;
  }
  mincostflow mcf(N*101+2);
  int s = N*101;
  int t = s + 1;
  for (int i = 0; i < K; i++) {
    mcf.add(s, A[i], 1, 0);
  }
  for (int i = 0; i <= 100; i++) {
    mcf.add(N * i, t, K, C*i);
  }
  // Combine loops: for each time step, add stay edges and movement edges
  for (int i = 0; i < 100; i++) {
    for (int j = 0; j < N; j++) {
      mcf.add(i*N+j, (i+1)*N+j, K, 0);
    }
    for (int j = 0; j < M; j++) {
      ll cost_base = D;
      for (int k = 1; k <= K; k++) {
        ll cost = (2*k - 1) * cost_base;
        mcf.add(N*i + us[j], N*(i+1) + vs[j], 1, cost);
        mcf.add(N*i + vs[j], N*(i+1) + us[j], 1, cost);
      }
    }
  }
  cout << mcf.run(s, t, K) << '\n';
}
